function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 1 || n > 30000) return 'n is a whole number from 1 to 30000.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'A tree on n nodes has exactly n - 1 edges.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (![a, b].every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Edge endpoints are nodes from 0 to n - 1.';
    if (a === b) return 'An edge must join two different nodes.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'The edges must not form a cycle.';
    root[ra] = rb;
  }
  return null;
}

